        animation_res = "15061/anime_d.prefab",
        trigger_mode = 2
      },
      [5] = {
        qq_res = "15061/anime_d.prefab",
        speak_role_id = 1,
        sentence = "空气里有毒气。",
        animation_mode = 1,
        animation_res = "15061/anime_d.prefab",
        trigger_mode = 2
      },
      [6] = {
        qq_res = "15061/anime_d.prefab",
        speak_role_id = 5,
        sentence = "嗯？可警报仪没有响啊？",
        animation_mode = 1,
        animation_res = "15061/anime_d.prefab",
        trigger_mode = 2
      },
      [7] = {
        qq_res = "15061/anime_d.prefab",
        speak_role_id = 1,
        sentence = "机器总有失灵的时候，比起依赖机器，你没发现空气里有深色气雾，还伴着一股刺鼻气味吗？",
