        animation_res = "15061/anime_d.prefab",
        trigger_mode = 2
      },
      [8] = {
        qq_res = "15061/anime_d.prefab",
        speak_role_id = 5,
        sentence = "好像是有——噢！！Σ(⊙▽⊙\"！！",
