        animation_res = "15061/anime_d.prefab",
        trigger_mode = 2
      },
      [9] = {
        qq_res = "15061/anime_d.prefab",
        speak_role_id = 1,
        sentence = "……反应这么慢，活到今天真是个奇迹。",
        animation_mode = 1,
        animation_res = "15061/anime_d.prefab",
        trigger_mode = 2
      },
      [10] = {
        qq_res = "15061/anime_d.prefab",
        speak_role_id = 5,
        sentence = "不是啦李泽言。",
        animation_mode = 1,
        animation_res = "15061/anime_d.prefab",
        trigger_mode = 2
      },
      [11] = {
        qq_res = "15061/anime_d.prefab",
        speak_role_id = 5,
        sentence = "是我刚才吃完牛肉罐头有点意犹未尽，就一直点着火让牛肉香扩散在房间里，忘记灭了……",
        animation_mode = 1,
        animation_res = "15061/anime_d.prefab",
        trigger_mode = 2
      },
      [12] = {
        qq_res = "15061/anime_d.prefab",
        speak_role_id = 5,
        sentence = "所以……应该是罐头被火烧烂了。",
        animation_mode = 1,
        animation_res = "15061/anime_d.prefab",
        trigger_mode = 2
      }
    },
    [14005] = {
      [1] = {
        qq_res = "15061/anime_e.prefab",
        speak_role_id = 5,
        sentence = "你知不知道这个钟楼有个秘-密-传-说——？",
        animation_mode = 1,
        animation_res = "15061/anime_e.prefab",
        trigger_mode = 2
      },
      [2] = {
        qq_res = "15061/anime_e.prefab",
        speak_role_id = 1,
        sentence = "……方圆几里只有你和我，没必要压低嗓子说话。",
        animation_mode = 1,
        animation_res = "15061/anime_e.prefab",
        trigger_mode = 2
      },
      [3] = {
        qq_res = "15061/anime_e.prefab",
        speak_role_id = 5,
        sentence = "我几个月前听人说，这个时钟自从一场地震后就走时就不准了，每转一圈就会慢3分钟。",
        animation_mode = 1,
        animation_res = "15061/anime_e.prefab",
        trigger_mode = 2
      },
      [4] = {
        qq_res = "15061/anime_e.prefab",
        speak_role_id = 5,
        sentence = "但你看它现在的时间，你发现什么了吗？",
