        animation_res = "15061/anime_e.prefab",
        trigger_mode = 2
      },
      [5] = {
        qq_res = "15061/anime_e.prefab",
        speak_role_id = 1,
        sentence = "嗯，是准的。",
        animation_mode = 1,
        animation_res = "15061/anime_e.prefab",
        trigger_mode = 2
      },
      [6] = {
        qq_res = "15061/anime_e.prefab",
        speak_role_id = 5,
        sentence = "所以啊，传闻里有位时间之神每天都会降临到这里，让时间重新回到正轨上。",
        animation_mode = 1,
        animation_res = "15061/anime_e.prefab",
        trigger_mode = 2
      },
      [7] = {
        qq_res = "15061/anime_e.prefab",
        speak_role_id = 1,
        sentence = "(▼ - ▼)时间之神？",
        animation_mode = 1,
        animation_res = "15061/anime_e.prefab",
        trigger_mode = 2
      },
      [8] = {
        qq_res = "15061/anime_e.prefab",
        speak_role_id = 5,
        sentence = "嗯！你别不信哦——",
        animation_mode = 1,
        animation_res = "15061/anime_e.prefab",
        trigger_mode = 2
      },
      [9] = {
        qq_res = "15061/anime_e.prefab",
        speak_role_id = 1,
        sentence = "你遇到他的话，有什么心愿？",
